<script setup>import {ref} from 'vue';import {supabase} from '../lib/supabase';const email=ref(''),password=ref(''),msg=ref('');async function login(){if(!supabase){msg.value='Demo mode: add Supabase environment variables to enable authentication.';return}const {error}=await supabase.auth.signInWithPassword({email:email.value,password:password.value});msg.value=error?error.message:'Signed in successfully.'}</script><template><div class="auth-wrap"><div class="auth-card"><router-link class="brand center" to="/"><span class="brand-mark">P</span><span><strong>PULSE</strong><small>BHARAT</small></span></router-link><h1>Welcome back</h1><p>Sign in to save stories, vote in polls and manage your subscription.</p><label>Email<input v-model="email" type="email" placeholder="you@example.com"></label><label>Password<input v-model="password" type="password" placeholder="••••••••"></label><button @click="login" class="primary">Sign in</button><div class="divider">or</div><button class="outline">Continue with Google</button><small>{{msg}}</small><p class="terms">New to Pulse? <b>Create an account</b></p></div></div></template>